from mnk.delivery import delivery_fee_kes, zone_of

def zone_fees(areas_km):
    out = {}
    for area, km in areas_km.items():
        if zone_of(area) == "X":
            out[area] = -1
        else:
            out[area] = delivery_fee_kes(round(km * 1000))
    return out

from collections import Counter
from mnk.staff import week_of

def week_counts(days):
    return dict(Counter(week_of(d) for d in days))

from mnk.delivery import delivery_fee_kes

def fee_labels(distances_m):
    return [label(delivery_fee_kes(m) * 100) for m in distances_m]  # fee is whole KES; label takes cents

from mnk.delivery import rider_minutes

def rider_plan(stops_km, rush_hour):
    return sum(rider_minutes(round(km * 1000), rush_hour) for km in stops_km)

from mnk.staff import hourly_rate_cents, shift_minutes

def late_shift_cost(roles):
    return sum(hourly_rate_cents(r) * shift_minutes("late") // 60 for r in roles)

def food_label(order):
    total = sum(line_total(code, qty) for code, qty in order.items())
    return label(total)

def cheapest_dish(codes):
    priced = []
    for code in sorted(set(codes)):
        try:
            priced.append((price_cents(code), code))
        except KeyError:
            continue  # not on our menu
    return min(priced)[1]
